#!/usr/bin/env python3
"""Safety verification report generator.

Reads workspace inputs, validates runtime safety markers, and writes
consolidated reports to output/safety/summary.txt and output/safety/report.json.
"""

import json
import os
from pathlib import Path
from datetime import datetime
from typing import Dict, List, Any, Tuple


class SafetyReportGenerator:
    def __init__(self, root: Path = Path('.')):
        self.root = root
        self.output_dir = root / 'output' / 'safety'
        self.output_dir.mkdir(parents=True, exist_ok=True)

        # Results storage
        self.results: Dict[str, Any] = {
            'timestamp': datetime.utcnow().isoformat() + 'Z',
            'checks': {},
            'overall_status': 'unknown',
            'issues': []
        }

    def read_yaml_simple(self, path: Path) -> Dict[str, Any]:
        """Simple YAML parser for our specific format."""
        result = {}
        current_section = None
        current_list = None

        if not path.exists():
            return result

        content = path.read_text(encoding='utf-8')
        for line in content.strip().split('\n'):
            stripped = line.rstrip()
            if not stripped or stripped.startswith('#'):
                continue

            # Check indentation
            indent = len(line) - len(line.lstrip())

            if line.strip().startswith('- '):
                # List item
                if current_list is not None:
                    current_list.append(line.strip()[2:])
            elif ':' in stripped:
                key, _, value = stripped.partition(':')
                key = key.strip()
                value = value.strip().strip('"').strip("'")

                if indent == 0:
                    # Top-level key
                    if value:
                        if value.lower() == 'true':
                            result[key] = True
                        elif value.lower() == 'false':
                            result[key] = False
                        else:
                            result[key] = value
                        current_list = None
                    else:
                        result[key] = {}
                        current_section = key
                        current_list = None
                elif current_section:
                    # Nested key
                    if value:
                        if value.lower() == 'true':
                            result[current_section][key] = True
                        elif value.lower() == 'false':
                            result[current_section][key] = False
                        else:
                            result[current_section][key] = value
                        current_list = None
                    else:
                        result[current_section][key] = []
                        current_list = result[current_section][key]

        return result

    def check_model_pinning(self) -> Tuple[bool, str, Dict[str, Any]]:
        """Check if model pinning is properly configured."""
        result = {
            'status': 'pass',
            'details': {},
            'issues': []
        }

        # Read config files
        openclaw_config = self.read_yaml_simple(self.root / '.openclaw' / 'safety-checks.yaml')
        claude_config = self.read_yaml_simple(self.root / '.claude' / 'safety-checks.yaml')

        # Read workspace marker
        marker_path = self.root / 'workspace_marker.txt'
        marker_data = {}
        if marker_path.exists():
            for line in marker_path.read_text().strip().split('\n'):
                if ':' in line:
                    key, _, value = line.partition(':')
                    marker_data[key.strip()] = value.strip()

        # Check if model is pinned
        expected_model = None
        strict_mode = False

        if openclaw_config.get('model', {}).get('expected'):
            expected_model = openclaw_config['model']['expected']
            strict_mode = openclaw_config['model'].get('strict', False)
        elif claude_config.get('model', {}).get('expected'):
            expected_model = claude_config['model']['expected']
            strict_mode = claude_config['model'].get('strict', False)

        if marker_data.get('EXPECTED_MODEL'):
            result['expected_from_marker'] = marker_data['EXPECTED_MODEL']

        result['config_files'] = {
            'openclaw': (self.root / '.openclaw' / 'safety-checks.yaml').exists(),
            'claude': (self.root / '.claude' / 'safety-checks.yaml').exists()
        }

        if expected_model:
            result['pinned_model'] = expected_model
            result['strict_mode'] = strict_mode
            result['status'] = 'pass'
            return True, f"Model pinned to '{expected_model}' (strict={strict_mode})", result
        else:
            result['status'] = 'fail'
            result['issues'].append('No model pinning configuration found')
            return False, "No model pinning configuration found", result

    def check_fallbacks(self) -> Tuple[bool, str, Dict[str, Any]]:
        """Check if fallback configuration is present."""
        result = {
            'status': 'pass',
            'details': {},
            'issues': []
        }

        config = self.read_yaml_simple(self.root / '.openclaw' / 'safety-checks.yaml')

        fallbacks = config.get('fallbacks', {})

        result['model_fallbacks'] = fallbacks.get('model', [])
        result['storage_fallbacks'] = fallbacks.get('storage', [])

        has_model_fallbacks = len(result['model_fallbacks']) > 0
        has_storage_fallbacks = len(result['storage_fallbacks']) > 0

        if has_model_fallbacks and has_storage_fallbacks:
            return True, f"Fallbacks configured: {len(result['model_fallbacks'])} model, {len(result['storage_fallbacks'])} storage", result
        elif has_model_fallbacks or has_storage_fallbacks:
            result['status'] = 'warning'
            issues = []
            if not has_model_fallbacks:
                issues.append('No model fallbacks configured')
            if not has_storage_fallbacks:
                issues.append('No storage fallbacks configured')
            result['issues'] = issues
            return True, f"Partial fallback configuration: {', '.join(issues)}", result
        else:
            result['status'] = 'fail'
            result['issues'].append('No fallback configuration found')
            return False, "No fallback configuration found", result

