            for line in marker_path.read_text().strip().split('\n'):
                if 'CACHE_TTL_SECONDS=' in line:
                    cache_ttl = int(line.split('=')[1])

        result['ttl_seconds'] = cache_ttl

        # Read staleness log
        staleness_log = self.root / '.openclaw' / 'cache' / 'staleness.log'
        stale_entries = []
        fresh_entries = []

        if staleness_log.exists():
            for line in staleness_log.read_text().strip().split('\n'):
                if not line.strip():
                    continue
                parts = line.split('|')
                entry = {'raw': line}
                for part in parts:
                    if '=' in part:
                        key, value = part.split('=', 1)
                        entry[key.strip()] = value.strip()

                age = int(entry.get('age_seconds', 0))
                if age > cache_ttl:
                    stale_entries.append(entry)
                else:
                    fresh_entries.append(entry)

        result['stale_entries'] = stale_entries
        result['fresh_entries'] = fresh_entries
        result['stale_count'] = len(stale_entries)
        result['fresh_count'] = len(fresh_entries)

        if stale_entries:
            result['status'] = 'fail'
            result['issues'].append(f"Found {len(stale_entries)} stale cache entries")
            return False, f"Cache staleness detected: {len(stale_entries)} stale entries (TTL={cache_ttl}s)", result
        else:
            return True, f"Cache is fresh: {len(fresh_entries)} entries within TTL ({cache_ttl}s)", result

