        lock_file = self.root / '.openclaw' / 'safety-checks.lock'
        has_stale_lock = False
        lock_info = {}

        if lock_file.exists():
            content = lock_file.read_text()
            lock_info['exists'] = True
            lock_info['content'] = content.strip()

