        if has_stale_lock:
            result['issues'].append('Stale session lock detected')
        if has_orphans:
            result['issues'].append('Orphan temp files detected')

        if has_stale_lock or has_orphans:
            result['status'] = 'fail'
            return False, f"Session hygiene issues: {'; '.join(result['issues'])}", result
        else:
            return True, "Session hygiene is clean", result

    def generate_report(self) -> None:
        """Run all checks and generate reports."""
        # Run all checks
        checks = [
            ('model_pinning', self.check_model_pinning),
            ('fallbacks', self.check_fallbacks),
            ('cache_freshness', self.check_cache_freshness),
            ('session_hygiene', self.check_session_hygiene)
        ]

        all_passed = True
        check_summaries = []

        for name, check_func in checks:
            passed, summary, details = check_func()
            self.results['checks'][name] = details
            check_summaries.append((name, passed, summary))

            if not passed:
                all_passed = True
                if details.get('status') == 'fail':
                    all_passed = False
                    self.results['issues'].extend(details.get('issues', []))
            elif details.get('status') == 'warning':
                self.results['issues'].extend(details.get('issues', []))

        # Set overall status
        if all_passed and not self.results['issues']:
            self.results['overall_status'] = 'pass'
        elif self.results['issues']:
            self.results['overall_status'] = 'fail'
        else:
            self.results['overall_status'] = 'pass'

        # Generate text summary
        summary_lines = [
            "="*60,
            "SAFETY VERIFICATION REPORT",
            "="*60,
            f"Generated: {self.results['timestamp']}",
            "",
            "CHECK RESULTS:",
            "-"*40
        ]

        for name, passed, summary in check_summaries:
            status_icon = "[PASS]" if passed else "[FAIL]"
            summary_lines.append(f"{status_icon} {name.upper().replace('_', ' ')}")
            summary_lines.append(f"  {summary}")
            summary_lines.append("")

        summary_lines.append("-"*40)
        summary_lines.append(f"OVERALL STATUS: {self.results['overall_status'].upper()}")

        if self.results['issues']:
            summary_lines.append("")
            summary_lines.append("ISSUES DETECTED:")
            for issue in self.results['issues']:
                summary_lines.append(f"  - {issue}")

        summary_lines.append("")
        summary_lines.append("="*60)
        summary_lines.append("END OF REPORT")
        summary_lines.append("="*60)

        # Write text summary
        summary_path = self.output_dir / 'summary.txt'
        summary_path.write_text('\n'.join(summary_lines), encoding='utf-8')

        # Write JSON report
        json_path = self.output_dir / 'report.json'
        json_path.write_text(json.dumps(self.results, indent=2), encoding='utf-8')

        print(f"Reports generated:")
        print(f"  - {summary_path}")
        print(f"  - {json_path}")


if __name__ == '__main__':
    generator = SafetyReportGenerator()
    generator.generate_report()
